function errorMessage(reason: unknown) { return reason && typeof reason === 'object' && 'message' in reason ? String(reason.message) : 'The student could not be saved.'; }
function initials(name: string) { return name.split(/\s+/).slice(0, 2).map((part) => part[0]).join('').toUpperCase(); }
function cleanPhone(value: unknown) { return String(value || '').replace(/[^0-9+]/g, ''); }
function subjectName(record: ClassioRecord) { return canonicalSubjectLabel(record.subject_custom || record.subject); }

