  const addressPractice = async (assignmentId: string, topicId: string) => { const key = `${assignmentId}:${topicId}`; setProgramBusy(key); setActionMessage(''); try { await addressTeacherPracticeRequest(assignmentId, topicId); setActionMessage(t('students.practiceAddressed')); await onRefresh(); } catch (reason) { setActionMessage(reason instanceof Error ? reason.message : t('students.topicUpdateFailed')); } finally { setProgramBusy(''); } };
  const filteredPrograms = workspace.programs.filter(inLearningSubject); const programPages = Math.max(1, filteredPrograms.length); const currentProgramPage = Math.min(programPage, programPages); const pagedPrograms = filteredPrograms.slice(currentProgramPage - 1, currentProgramPage);
  const filteredRecommendations = recommendations.filter((item) => learningSubject === '__all__' || canonicalSubjectKey(item.subject) === canonicalSubjectKey(learningSubject));
  const assignedResourceKeys = new Set(workspace.assignments.filter((row) => String(row.status || '') !== 'archived' && row.source_record_id).map((row) => `${({ lesson_plan_topic: 'plan', lesson_plan: 'plan', plan: 'plan', worksheet: 'worksheet', exam: 'exam', video: 'video' } as Record<string, string>)[String(row.assignment_type || row.source_type)] || String(row.assignment_type || row.source_type)}:${String(row.source_record_id)}`));
