            <View style={styles.assignmentCardFacts}><Text style={[styles.assignmentFact, { color: score === null || score === undefined ? colors.muted : Number(score) < 65 ? colors.danger : Number(score) < 85 ? colors.orange : colors.success }]}>{score === null || score === undefined ? '—' : `${score}%`}</Text><Text style={[styles.assignmentFact, { color: requestColor }]}>⚑ {requestCount} {t('assignmentLabels.requests')}</Text></View>
