  const statusControl = <View style={{ width: 170 }}><SelectField label={t('students.filterStatus')} value={activityFilter} options={[{ value: 'all', label: t('students.filter.all') }, { value: 'active', label: t('students.filter.active') }, { value: 'inactive', label: t('students.filter.inactive') }]} onChange={(value) => { setActivityFilter(value as typeof activityFilter); setRosterPage(1); }} /></View>;
